+// API keys and roles. Keys live in `store.data.apiKeys` as
+// { key, name, role }. A viewer may only read; a cook may also cook, record
+// waste, log temperatures and enter stock-take counts; a manager may do
+// everything. Routes are named "METHOD /pattern", as in the router.
+import { createHash, timingSafeEqual } from "node:crypto";
+
+export const ROLES = ["viewer", "cook", "manager"];
+
+// Changing routes a cook may call besides reading.
+const COOK_ROUTES = new Set([
+  "POST /recipes/:id/cook",
+  "POST /batches/:id/waste",
+  "POST /temperatures",
+  "POST /stocktakes/:id/counts",
+]);
+
+// Reading routes only managers may call.
+const MANAGER_ONLY_READS = new Set(["GET /audit"]);
+
+const digest = (s) => createHash("sha256").update(String(s)).digest();
+
+/** The API key record for a presented key, or null when unknown. */
+export function findKey(store, presented) {
+  if (typeof presented !== "string" || presented === "") return null;
+  const want = digest(presented);
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) {
+    if (timingSafeEqual(digest(k.key), want) && ROLES.includes(k.role)) found ??= k;
+  }
+  return found;
+}
+
+/** Whether `role` may call `route` ("METHOD /pattern"). */
+export function allowed(role, route) {
+  if (role === "manager") return true;
+  if (MANAGER_ONLY_READS.has(route)) return false;
+  if (route.startsWith("GET ")) return role === "viewer" || role === "cook";
+  return role === "cook" && COOK_ROUTES.has(route);
+}
