+// The audit log: one entry per request that changes data (or tries to).
+// Entries are never edited or deleted.
+
+/** Appends an audit entry { at, keyName, method, path, status } and returns it. */
+export function recordAudit(store, { at, keyName = null, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].sort((a, b) => b.at.localeCompare(a.at) || b.id - a.id);
+}
