+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, as, MANAGER } from "./helpers.js";
+
+const VIEWER = as("viewer");
+const COOK = as("cook");
+
+test("no key or an unknown key is 401 in the error shape", async () => {
+  const { handle } = app();
+  const none = await handle({ path: "/items" });
+  assert.equal(none.status, 401);
+  assert.equal(none.body.error.code, "unauthorized");
+  assert.equal(typeof none.body.error.message, "string");
+  const wrong = await handle({ path: "/items", headers: { authorization: "Bearer nope" } });
+  assert.equal(wrong.status, 401);
+  const notBearer = await handle({ path: "/items", headers: { Authorization: `Basic ${MANAGER.authorization.slice(7)}` } });
+  assert.equal(notBearer.status, 401);
+  const anyCase = await handle({ path: "/items", headers: { Authorization: MANAGER.authorization } });
+  assert.equal(anyCase.status, 200);
+});
+
+test("a viewer may only read", async () => {
+  const { handle, store } = app();
+  assert.equal((await handle({ headers: VIEWER, path: "/items" })).status, 200);
+  const before = JSON.stringify(store.data.batches);
+  const cook = await handle({ headers: VIEWER, method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  assert.equal(cook.status, 403);
+  assert.equal(cook.body.error.code, "forbidden");
+  assert.equal(JSON.stringify(store.data.batches), before);
+  assert.equal((await handle({ headers: VIEWER, path: "/audit" })).status, 403);
+});
+
+test("a cook may cook, waste, log temperatures and count, nothing else that changes data", async () => {
+  const { handle } = app();
+  assert.equal((await handle({ headers: COOK, method: "POST", path: "/recipes/1/cook", body: { portions: 1 } })).status, 200);
+  assert.equal((await handle({ headers: COOK, method: "POST", path: "/batches/6/waste", body: { qty: 0.5 } })).status, 201);
+  assert.equal((await handle({ headers: COOK, method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 } })).status, 201);
+  assert.equal((await handle({ headers: COOK, method: "POST", path: "/stocktakes", body: { location: "dry" } })).status, 403);
