+  assert.equal((await handle({ headers: COOK, method: "POST", path: `/stocktakes/${take.body.id}/finish` })).status, 403);
+  assert.equal((await handle({ headers: COOK, method: "POST", path: "/orders", body: { supplierId: 1, lines: [] } })).status, 403);
+  assert.equal((await handle({ headers: COOK, path: "/reports/stock-value" })).status, 200);
+  assert.equal((await handle({ headers: COOK, path: "/audit" })).status, 403);
+});
+
+test("changing requests are audited, newest first, for managers only", async () => {
+  const { handle } = app();
+  await handle({ headers: COOK, method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  await handle({ headers: VIEWER, method: "POST", path: "/batches/6/waste", body: { qty: 0.5 } });
